    gripper_name: str | list[str] = "gripper",
    env_id: int | None = None,
):
    """Check if an object has been dropped (in contact with none of the given grippers)."""
    world = get_world(env)
    result = gripper_detached(world, object, gripper_name, env_id=env_id)
